const scheduleTaskExecutionReconcile = `-- name: ScheduleTaskExecutionReconcile :one
UPDATE work_items
SET task_next_reconcile_at=CASE
      WHEN task_next_reconcile_at<=clock_timestamp() THEN clock_timestamp()
      ELSE LEAST(
        clock_timestamp()+make_interval(secs=>$1::int),
        (SELECT attempt.deadline_at FROM task_attempts attempt
         WHERE attempt.task_id=work_items.id
           AND attempt.generation=work_items.task_execution_generation
           AND attempt.status='running')
      )
    END,
    task_worker_id=NULL,
    task_lease_token_hash=NULL,
    task_lease_expires_at=NULL
WHERE id=$2::text
  AND tenant_id=$3::text
  AND task_execution_generation=$4::bigint
  AND task_execution_revision=$5::bigint
  AND task_control_revision=$6::bigint
  AND task_worker_id=$7::text
  AND task_lease_generation=$8::bigint
  AND task_lease_token_hash=$9::bytea
  AND task_lease_expires_at>clock_timestamp()
RETURNING id, tenant_id, number, kind, title, description, priority, state, resolution, version, created_by_actor_id, updated_by_actor_id, archived_at, created_at, updated_at, task_source_key, task_execution_generation, task_execution_status, task_execution_revision, task_execution_reason_code, task_desired_control, task_control_revision, task_control_settled_revision, task_control_outcome, task_control_source_kind, task_control_source_id, task_control_requested_by_actor_id, task_control_requested_at, task_control_payload, task_execution_updated_at, task_next_reconcile_at, task_worker_id, task_lease_token_hash, task_lease_generation, task_lease_expires_at
`

type ScheduleTaskExecutionReconcileParams struct {
	ReconcileAfterSeconds     int32  `json:"reconcile_after_seconds"`
	TaskID                    string `json:"task_id"`
	TenantID                  string `json:"tenant_id"`
	Generation                int64  `json:"generation"`
	ExpectedExecutionRevision int64  `json:"expected_execution_revision"`
	ExpectedControlRevision   int64  `json:"expected_control_revision"`
	WorkerID                  string `json:"worker_id"`
	LeaseGeneration           int64  `json:"lease_generation"`
	LeaseTokenHash            []byte `json:"lease_token_hash"`
}

// The running Attempt's deadline caps the delay, so the timeout needs no
// polling; LEAST ignores the NULL of an Attempt without a deadline. A claim
// sets the time to the lease end and each lease heartbeat keeps it there, so
// a time already due during the lease comes from a writer that made the Task
// due, such as a finished participant Run; it stays due instead of moving
// later.
func (q *Queries) ScheduleTaskExecutionReconcile(ctx context.Context, arg ScheduleTaskExecutionReconcileParams) (WorkItem, error) {
	row := q.db.QueryRow(ctx, scheduleTaskExecutionReconcile,
		arg.ReconcileAfterSeconds,
		arg.TaskID,
		arg.TenantID,
		arg.Generation,
		arg.ExpectedExecutionRevision,
		arg.ExpectedControlRevision,
		arg.WorkerID,
		arg.LeaseGeneration,
		arg.LeaseTokenHash,
	)
	var i WorkItem
	err := row.Scan(
		&i.ID,
		&i.TenantID,
		&i.Number,
		&i.Kind,
		&i.Title,
		&i.Description,
		&i.Priority,
		&i.State,
		&i.Resolution,
		&i.Version,
		&i.CreatedByActorID,
		&i.UpdatedByActorID,
		&i.ArchivedAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.TaskSourceKey,
		&i.TaskExecutionGeneration,
		&i.TaskExecutionStatus,
		&i.TaskExecutionRevision,
		&i.TaskExecutionReasonCode,
		&i.TaskDesiredControl,
		&i.TaskControlRevision,
		&i.TaskControlSettledRevision,
		&i.TaskControlOutcome,
		&i.TaskControlSourceKind,
		&i.TaskControlSourceID,
		&i.TaskControlRequestedByActorID,
		&i.TaskControlRequestedAt,
		&i.TaskControlPayload,
		&i.TaskExecutionUpdatedAt,
		&i.TaskNextReconcileAt,
		&i.TaskWorkerID,
		&i.TaskLeaseTokenHash,
		&i.TaskLeaseGeneration,
		&i.TaskLeaseExpiresAt,
	)
	return i, err
}

